// Process and format the available faculty candidates
const items = $input.all();
const payload = items[0].json;

const freeTeachers = payload.availableFaculty || [];
const formattedResults = freeTeachers.map(teacher => ({
  id: teacher.id,
  faculty_id: teacher.faculty_id,
  name: teacher.full_name,
  contact_number: teacher.phone,
  email: teacher.email,
  department: teacher.department,
  designation: teacher.designation,
  whatsapp_link: `https://wa.me/${teacher.phone.replace(/[^0-9]/g, '')}?text=Dear%20Prof.%20${encodeURIComponent(teacher.full_name)},%20can%20you%20please%20substitute%20for%20my%20period%20on%20${payload.criteria.day}%20Period%20${payload.criteria.period}?`,
  free_verified: true
}));

return [{
  json: {
    status: "success",
    engine: "n8n Background Pipeline",
    total_candidates_found: formattedResults.length,
    criteria: payload.criteria,
    pipeline_trace: payload.pipelineTrace,
    candidates: formattedResults
  }
}];
